def allocate_cents(total, weights):
    if isinstance(total, bool) or not isinstance(total, int):
        raise TypeError('total must be an integer')
    if not isinstance(weights, list):
        raise TypeError('weights must be a list')
    for weight in weights:
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError('weights must contain integers')
    if total < 0:
        raise ValueError('total must be nonnegative')
    if not weights:
        raise ValueError('weights must be nonempty')
    if any(weight <= 0 for weight in weights):
        raise ValueError('weights must be positive')
    denominator = sum(weights)
    shares = [divmod(total * weight, denominator) for weight in weights]
    allocations = [share[0] for share in shares]
    remaining = total - sum(allocations)
    order = sorted(range(len(weights)), key=lambda index: (-shares[index][1], index))
    for index in order[:remaining]:
        allocations[index] += 1
    return allocations

import math

def categorical_loss_grad(logits, labels):
    if not isinstance(logits, list) or not logits:
        raise ValueError('logits must be a nonempty list')
    if not isinstance(labels, list) or len(labels) != len(logits):
        raise ValueError('labels must match the batch')
    if not isinstance(logits[0], list) or len(logits[0]) < 2:
        raise ValueError('at least two classes are required')
    n = len(logits)
    c = len(logits[0])
    rows = []
    for row in logits:
        if not isinstance(row, list) or len(row) != c:
            raise ValueError('logits must be rectangular')
        converted = []
        for value in row:
            if not isinstance(value, (int, float)):
                raise ValueError('logits must be numeric')
            try:
                value = float(value)
            except (TypeError, ValueError, OverflowError):
                raise ValueError('logits must be finite floats') from None
            if not math.isfinite(value):
                raise ValueError('logits must be finite')
            converted.append(value)
        rows.append(converted)
    for label in labels:
        if isinstance(label, bool) or not isinstance(label, int):
            raise ValueError('labels must be integer indices')
        if not 0 <= label < c:
            raise ValueError('label outside class range')
    mean_loss = 0.0
    gradient = []
    for row, label in zip(rows, labels):
        maximum = max(row)
        weights = [math.exp(value - maximum) for value in row]
        total = math.fsum(weights)
        gap = maximum - row[label]
        # Scale before subtracting only when the unscaled gap overflows.
        scaled_gap = gap / n if math.isfinite(gap) else maximum / n - row[label] / n
        mean_loss += scaled_gap + math.log(total) / n
        gradient.append([(weight / total - (1.0 if j == label else 0.0)) / n
                         for j, weight in enumerate(weights)])
    return mean_loss, gradient

def check_contract(fn):
    class IntegerSubclass(int):
        pass

    def valid(value):
        result = fn(value)
        assert isinstance(result, int) and not isinstance(result, bool), (value, result)
        assert result == value, (value, result)

    def raises(value, expected):
        try:
            fn(value)
        except Exception as error:
            assert isinstance(error, expected), (value, expected, type(error))
        else:
            raise AssertionError(('expected exception', value, expected))

    for value in (1, 2, 80, 443, 1024, 32768, 65534, 65535, IntegerSubclass(8080)):
        valid(value)
    for value in (0, -1, -65535, 65536, 65537, 10 ** 100):
        raises(value, ValueError)
    for value in (True, False, None, '80', '', b'80', 1.0, 65535.0, 0.0,
                  -1.0, float('nan'), float('inf'), 80 + 0j, [], {}, (), set()):
        raises(value, TypeError)
    valid(1)
    valid(65535)
    valid(8080)
